INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Versionshistorie ohne Datum sinnvoll?', 2, '[{"text": "Nein", "correct": true, "because": "Zeitpunkt gibt Kontext"}, {"text": "Ja", "correct": false, "because": "Fehlende Chronologie"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Versionshistorie?', 3, '[{"text": "Nachverfolgbarkeit", "correct": true, "because": "Zeigt Änderungsverlauf"}, {"text": "Performance", "correct": false, "because": "Kein direkter Einfluss"}, {"text": "Design", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einer Versionshistorie?', 5, '[{"text": "Versionsnummer", "correct": true, "because": "Identifiziert Zustand"}, {"text": "Änderungsbeschreibung", "correct": true, "because": "Erklärt Modifikationen"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}, {"text": "Hardware-Details", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Versionshistorie braucht Commit-Details. b) Sie ist nur für Entwickler.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) auch für QA und Management"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einer Versionshistorie?', 4, '[{"text": "Änderungen", "correct": false, "because": "Kern der Historie"}, {"text": "Datum", "correct": false, "because": "Zeigt Zeitpunkt"}, {"text": "Schriftgröße", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Versionshistorie immer manuell geführt wird?', 2, '[{"text": "Nein", "correct": true, "because": "Tools wie Git automatisieren"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool nutze ich für eine Versionshistorie?', 3, '[{"text": "Git", "correct": true, "because": "Standard für Versionierung"}, {"text": "Notepad", "correct": false, "because": "Keine Struktur"}, {"text": "E-Mail", "correct": false, "because": "Unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen eine Versionshistorie effektiv?', 5, '[{"text": "Klarheit", "correct": true, "because": "Fördert Verständnis"}, {"text": "Vollständigkeit", "correct": true, "because": "Alle Änderungen abdecken"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Irrelevant"}, {"text": "Lange Texte", "correct": false, "because": "Ermüdend"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Versionshistorie ist nur für Code. b) Dokumentation ersetzt sie. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "Auch für andere Inhalte, ergänzt Doku"}, {"text": "Beides stimmt", "correct": false, "because": "Nicht korrekt"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Versionshistorie?', 4, '[{"text": "Versionsnummer", "correct": false, "because": "Identifiziert Zustand"}, {"text": "Änderungsgrund", "correct": false, "because": "Gibt Kontext"}, {"text": "Teamfotos", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine Versionshistorie nur für große Projekte?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte profitieren"}, {"text": "Ja", "correct": false, "because": "Nicht exklusiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Details sind in einer Versionshistorie entscheidend?', 4, '[{"text": "Änderungsdatum", "correct": true, "because": "Zeigt Zeitpunkt"}, {"text": "Beschreibung", "correct": true, "because": "Erklärt Modifikation"}, {"text": "UI-Design", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Versionshistorie nur einmal erstellt wird. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Fortlaufend aktualisiert"}, {"text": "Ja", "correct": false, "because": "Dynamisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer Versionshistorie?', 3, '[{"text": "Präzision", "correct": true, "because": "Sichert Klarheit"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Qualität zählt"}, {"text": "Visuelle Effekte", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Versionshistorie braucht Versionsnummern. b) Sie ersetzt Tests.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist separat"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gute Versionshistorie?', 5, '[{"text": "Rückverfolgbarkeit", "correct": true, "because": "Zeigt Verlauf"}, {"text": "Fehlerbehebung", "correct": true, "because": "Identifiziert Ursachen"}, {"text": "Hohe Kosten", "correct": false, "because": "Kein Vorteil"}, {"text": "Schnelle Entwicklung", "correct": false, "because": "Indirekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Versionshistorie unwichtig?', 3, '[{"text": "Änderungsdetails", "correct": false, "because": "Kern der Historie"}, {"text": "Zeitstempel", "correct": false, "because": "Zeigt Chronologie"}, {"text": "Monitorgröße", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzt eine Versionshistorie die Dokumentation?', 3, '[{"text": "Nein", "correct": true, "because": "Ergänzen sich"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Zwecke"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Versionshistorie nur für Software ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für andere Inhalte"}, {"text": "Ja", "correct": false, "because": "Nicht exklusiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für eine Versionshistorie entscheidend?', 4, '[{"text": "Konsistenz", "correct": true, "because": "Sichert Verlässlichkeit"}, {"text": "Hohe Komplexität", "correct": false, "because": "Verwirrt"}, {"text": "Manuelle Eingabe", "correct": false, "because": "Automatisierung besser"}]');
